#ifndef LOTBOOK_HPP
#define LOTBOOK_HPP

#include <optional>
#include <stdexcept>
#include <string>
#include <vector>

namespace lotbook {

struct Batch {
    std::string id;
    int expiry;
    int qty;
    long unit_cost;
};

struct Pick {
    std::string batch;
    int expiry;
    int qty;
    long unit_cost;
};

class StockError : public std::runtime_error {
public:
    using std::runtime_error::runtime_error;
};

class StockBook {
public:
    void receive(const std::string &id, int qty, long unit_cost, int expiry);
    std::vector<Batch> batches() const;
    int on_hand(int today) const;
    long value(int today) const;
    std::optional<int> next_expiry(int today) const;
    std::vector<std::string> expiring_within(int today, int days) const;
    std::vector<Pick> issue(int qty, int today);
    void give_back(const Pick &p);
    std::vector<Batch> expire(int today);

private:
    std::vector<Batch> batches_; /* kept ordered by (expiry, id) */
    void insert_sorted(const Batch &b);
    int find(const std::string &id) const;
};

long cost_of(const std::vector<Pick> &picks);

}  // namespace lotbook

#endif

