    auto g_ = (got); \
    auto w_ = (want); \
    h_checks++; \
    if (!h_eq(g_, w_)) { \
        h_fails++; \
        std::printf("FAIL %s:%d: [%s] %s: got %s, want %s\n", __FILE__, __LINE__, std::string(ctx).c_str(), #got, h_show(g_).c_str(), h_show(w_).c_str()); } \
} while (0)

